"""User-authorized entry policy change plus read-only existing index recovery."""
from pathlib import Path
import base64,contextlib,hashlib,io,json,os,stat,zlib
state=Path('/home/jwk/y-aenv-control/relay-debian-clean-20261111')
entry=state/'entry.py'
oldsha='a60349eb2679f241e4f5fb46a6b88c8b6f51a6c48f80660d1848988718a9619d'
newsha='a186b8898c89c6d743b7792b0fb5d88ed9f1a478000142ee148914a3279a86dc'
raw=zlib.decompress(base64.b64decode(''))
index=zlib.decompress(base64.b64decode(''))
assert os.geteuid()==0 and state.resolve()==state and entry.resolve()==entry
row=entry.stat();assert row.st_uid==0 and stat.S_ISREG(row.st_mode) and not row.st_mode&0o077
current=entry.read_bytes();assert hashlib.sha256(current).hexdigest()==oldsha
assert hashlib.sha256(raw).hexdigest()==newsha
assert hashlib.sha256(index).hexdigest()=='4726a8468e5954007d195924844270a2a6b3bbabc17601c4c05aaf4de5f26e18'
compile(raw,'<new-entry>','exec');compile(index,'<saved-index-reader>','exec')
# Verify and read the small saved index before modifying the entry.
buffer=io.StringIO()
with contextlib.redirect_stdout(buffer):exec(compile(index,'<saved-index-reader>','exec'),{'__name__':'saved_index_reader'})
text=buffer.getvalue();assert 'UPLOAD_INDEX=' in text and 'SAVED_RESULTS=' in text and len(text.encode())<800000
backup=state/'entry.before-no-boot-20261123.py'
if backup.exists():assert backup.read_bytes()==current
else:
 fd=os.open(backup,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600)
 with os.fdopen(fd,'wb') as stream:stream.write(current);stream.flush();os.fsync(stream.fileno())
assert entry.read_bytes()==current
nextpath=state/'entry.no-boot-next-20261123.py'
fd=os.open(nextpath,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600)
with os.fdopen(fd,'wb') as stream:stream.write(raw);stream.flush();os.fsync(stream.fileno())
os.replace(nextpath,entry)
fd=os.open(state,os.O_RDONLY|os.O_DIRECTORY)
try:os.fsync(fd)
finally:os.close(fd)
assert hashlib.sha256(entry.read_bytes()).hexdigest()==newsha
print('ENTRY_POLICY_UPDATED='+json.dumps({'oldSha256':oldsha,'newSha256':newsha,'bootBlocksExecution':False,'backup':str(backup),'testsRepeated':False},separators=(',',':')),flush=True)
print(text,end='',flush=True)
